def h(x): return html.escape(str(x), quote=True)
def link(url, title): return f'<a href="{h(url)}">{h(title)}</a>'
def refs(*keys):
 return '<p class="eg-ref">依据：'+' · '.join(f'<a href="{h(SOURCES[k][1])}" target="_blank" rel="noopener noreferrer">{h(SOURCES[k][0])} ↗</a>' for k in keys)+'</p>'
def p(text): return '<p>'+text+'</p>'
def box(title, body, ident='', kind=''):
 return f'<section class="eg-box {kind}"'+(f' id="{h(ident)}"' if ident else '')+f'><h2>{title}</h2>{body}</section>'
def callout(title, text, kind=''):
 return f'<div class="eg-callout {kind}"><strong>{h(title)}</strong><p>{text}</p></div>'
def table(head, rows):
 return '<div class="eg-table-wrap"><table class="eg-table"><thead><tr>'+''.join('<th scope="col">'+h(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def steps(rows):
 return '<ol class="eg-steps">'+''.join('<li><div><h3>'+h(title)+'</h3><p>'+body+'</p></div></li>' for title,body in rows)+'</ol>'
def checks(ident, rows):
 return '<div class="eg-checks" data-eg-group="'+h(ident)+'">'+''.join(f'<label><input type="checkbox" data-eg-check="{h(ident)}-{i}"><span>{h(t)}</span></label>' for i,t in enumerate(rows))+'</div><div class="eg-check-foot"><span class="eg-check-status" role="status">仅为网页备忘，不改变游戏</span><button type="button" data-eg-reset="'+h(ident)+'">清除此页勾选</button></div>'
def node(name, effect, why, gate='连线路径可达；有本树可用点数', choose='', risk='', ident=''):
 return dict(name=name,effect=effect,why=why,gate=gate,choose=choose,risk=risk,id=ident)
