PAGES=[('atlas-start','异界入门',start_body),('atlas-passives','异界主树加点',passives_body),('atlas-activities','各玩法与专用天赋',activities_body),('atlas-masters','大师选择',masters_body),('atlas-other','其他玩法与养成',other_body),('atlas-sources','异界来源与检查边界',sources_body)]
def pages():
 out=[(rid,title,fn()) for rid,title,fn in PAGES]
 out.extend(('atlas-'+a['id'],a['name']+'玩法与天赋',activity_body(a)) for a in ACTIVITIES)
 return out

def search_entries():
 out=[]
 for rid,title,body in pages():
  text=re.sub('<[^>]+>',' ',body)
  out.append(dict(title=title+' / R22异界工作区',text=html.unescape(text),url=rid+'.html'))
 for i,n in enumerate(MAIN_NODES,1):
  out.append(dict(title='异界主树 / '+n['name'],text=' '.join(n.values()),url='atlas-passives.html#'+(n['id'] or 'node-'+str(i))))
 for a in ACTIVITIES:
  for i,n in enumerate(a['nodes'],1):
   out.append(dict(title=a['name']+'天赋 / '+n['name'],text=' '.join(n.values()),url='atlas-'+a['id']+'.html#'+(n['id'] or 'node-'+str(i))))
 return out

def write_data():
 data=dict(version='C R22',checked_at=DATE,scope='Atlas and activity trees; NOT character passives',rules=dict(priority_numbers='core target order, not point count',edges='not verified; follow game prerequisites',recommendation_author='本站新手研究补充；非Fubgun原文',build_snapshot='0.5.5',mechanics_through='0.5.5d',client_validated=False),main_nodes=MAIN_NODES,activities=ACTIVITIES,sources={k:dict(title=v[0],url=v[1],scope=v[2]) for k,v in SOURCES.items()})
 (ROOT/'data/R22异界玩法与节点.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
